import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const performOCR = async (base64Image: string, language: string = 'auto'): Promise<string> => {
  // Extract just the base64 data without the prefix
  const base64Data = base64Image.split(',')[1];

  const prompt = language === 'auto' 
    ? "Perform high-accuracy OCR on this image. Extract all readable text and maintain its structural formatting (paragraphs, lists, headings). If the text is in multiple languages, extract all of them."
    : `Perform high-accuracy OCR on this image, specifically focusing on ${language} text. Extract all readable text and maintain its structural formatting.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'image/png' } },
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1, // Low temperature for more deterministic OCR results
      }
    });

    return response.text || "No text could be extracted.";
  } catch (error) {
    console.error("OCR Service Error:", error);
    throw new Error("Failed to process image. Please check your internet connection and try again.");
  }
};

// Use global jsPDF from script tag
declare const jspdf: any;

export const generatePDF = async (text: string, fileName: string = 'ExtractedText.pdf') => {
  if (!text.trim()) return;

  const doc = new jspdf.jsPDF();
  const pageHeight = doc.internal.pageSize.height;
  const margin = 10;
  const maxLineWidth = doc.internal.pageSize.width - margin * 2;

  // Split text to fit page width
  const splitText = doc.splitTextToSize(text, maxLineWidth);

  let yPosition = 20;

  // Add title
  doc.setFontSize(16);
  doc.text("Smart OCR Pro - Extracted Text", margin, yPosition);
  yPosition += 10;

  doc.setFontSize(11);
  doc.setFont("helvetica", "normal");

  splitText.forEach((line: string) => {
    if (yPosition > pageHeight - margin) {
      doc.addPage();
      yPosition = margin + 10;
    }
    doc.text(line, margin, yPosition);
    yPosition += 6;
  });

  doc.save(fileName);
};

export const shareText = async (text: string) => {
  if (navigator.share) {
    try {
      await navigator.share({
        title: 'Extracted Text from Smart OCR Pro',
        text: text
      });
    } catch (err) {
      console.error('Sharing failed:', err);
    }
  } else {
    // Fallback: Copy to clipboard
    await navigator.clipboard.writeText(text);
    alert('Text copied to clipboard (Sharing not supported on this browser)');
  }
};

import React, { useReducer, useCallback, useRef } from 'react';
import { OCRState, OCRActionType, OCRAction } from './types';
import { performOCR } from './services/geminiService';
import { generatePDF, shareText } from './services/pdfService';
import { LANGUAGES, Icons } from './constants';

const initialState: OCRState = {
  image: null,
  extractedText: '',
  isProcessing: false,
  error: null,
  language: 'auto',
  autoDetect: true,
  history: []
};

function ocrReducer(state: OCRState, action: OCRAction): OCRState {
  switch (action.type) {
    case OCRActionType.SET_IMAGE:
      return { ...state, image: action.payload, extractedText: '', error: null };
    case OCRActionType.SET_TEXT:
      return { ...state, extractedText: action.payload, isProcessing: false };
    case OCRActionType.SET_PROCESSING:
      return { ...state, isProcessing: action.payload };
    case OCRActionType.SET_ERROR:
      return { ...state, error: action.payload, isProcessing: false };
    case OCRActionType.SET_LANGUAGE:
      return { ...state, language: action.payload };
    case OCRActionType.TOGGLE_AUTO_DETECT:
      return { ...state, autoDetect: !state.autoDetect };
    case OCRActionType.CLEAR_ALL:
      return { ...initialState, history: state.history };
    default:
      return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(ocrReducer, initialState);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, isCamera: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        dispatch({ type: OCRActionType.SET_IMAGE, payload: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const startOCR = async () => {
    if (!state.image) {
      dispatch({ type: OCRActionType.SET_ERROR, payload: 'Please select an image first.' });
      return;
    }

    dispatch({ type: OCRActionType.SET_PROCESSING, payload: true });
    try {
      const result = await performOCR(state.image, state.language);
      dispatch({ type: OCRActionType.SET_TEXT, payload: result });
    } catch (err: any) {
      dispatch({ type: OCRActionType.SET_ERROR, payload: err.message });
    }
  };

  const copyToClipboard = async () => {
    await navigator.clipboard.writeText(state.extractedText);
    // Simple toast-like feedback could be added here
  };

  return (
    <div className="min-h-screen flex flex-col max-w-lg mx-auto bg-white shadow-xl relative">
      {/* Top App Bar */}
      <header className="sticky top-0 z-50 bg-[#6750A4] text-white p-4 flex items-center justify-between m3-elevation-2 rounded-b-xl">
        <div className="flex items-center gap-3">
          <Icons.Scan />
          <h1 className="text-xl font-medium tracking-tight">Smart OCR Pro</h1>
        </div>
        <div className="flex gap-2">
          <button className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <Icons.Settings />
          </button>
          <button className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <Icons.Help />
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-6 pb-24">
        {/* Image Input Selection */}
        <section className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <button 
              onClick={() => cameraInputRef.current?.click()}
              className="flex flex-col items-center justify-center p-6 bg-[#EADDFF] text-[#21005D] rounded-3xl gap-2 hover:bg-[#D0BCFF] transition-all m3-elevation-1"
            >
              <Icons.Camera />
              <span className="text-sm font-semibold">Camera</span>
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex flex-col items-center justify-center p-6 bg-[#EADDFF] text-[#21005D] rounded-3xl gap-2 hover:bg-[#D0BCFF] transition-all m3-elevation-1"
            >
              <Icons.Gallery />
              <span className="text-sm font-semibold">Gallery</span>
            </button>
          </div>

          <input 
            type="file" 
            accept="image/*" 
            capture="environment" 
            ref={cameraInputRef} 
            onChange={(e) => handleFileChange(e, true)} 
            className="hidden" 
          />
          <input 
            type="file" 
            accept="image/*" 
            ref={fileInputRef} 
            onChange={(e) => handleFileChange(e)} 
            className="hidden" 
          />

          {/* Image Preview */}
          {state.image ? (
            <div className="relative group">
              <div className="rounded-3xl overflow-hidden bg-slate-100 border-2 border-dashed border-[#6750A4]/30 aspect-video flex items-center justify-center m3-elevation-1">
                <img src={state.image} alt="Captured" className="w-full h-full object-contain" />
              </div>
              <button 
                onClick={() => dispatch({ type: OCRActionType.SET_IMAGE, payload: null })}
                className="absolute top-2 right-2 p-1 bg-white/80 rounded-full text-red-500 shadow-sm"
              >
                <Icons.Trash />
              </button>
            </div>
          ) : (
            <div className="rounded-3xl overflow-hidden bg-slate-50 border-2 border-dashed border-slate-200 aspect-video flex flex-col items-center justify-center text-slate-400 gap-2">
              <div className="opacity-40"><Icons.Gallery /></div>
              <p className="text-sm">No image selected</p>
            </div>
          )}
        </section>

        {/* OCR Controls */}
        <section className="bg-[#F3EDF7] p-5 rounded-3xl space-y-4 m3-elevation-1">
          <h2 className="text-sm font-bold text-[#49454F] uppercase tracking-wider">Scan Options</h2>

          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-sm font-medium text-[#1C1B1F]">Auto-detect Language</label>
              <input 
                type="checkbox" 
                checked={state.autoDetect}
                onChange={() => dispatch({ type: OCRActionType.TOGGLE_AUTO_DETECT })}
                className="w-10 h-6 bg-[#E7E0EC] checked:bg-[#6750A4] rounded-full appearance-none transition-all cursor-pointer relative after:content-[''] after:absolute after:top-1 after:left-1 after:bg-white after:w-4 after:h-4 after:rounded-full after:transition-all checked:after:translate-x-4"
              />
            </div>

            {!state.autoDetect && (
              <div className="flex flex-col gap-1">
                <label className="text-xs text-[#6750A4] font-medium ml-1">Select Language</label>
                <select 
                  value={state.language}
                  onChange={(e) => dispatch({ type: OCRActionType.SET_LANGUAGE, payload: e.target.value })}
                  className="w-full p-3 bg-white rounded-xl border border-[#79747E] text-sm focus:outline-none focus:ring-2 focus:ring-[#6750A4]"
                >
                  {LANGUAGES.map(lang => (
                    <option key={lang.code} value={lang.code}>{lang.name}</option>
                  ))}
                </select>
              </div>
            )}

            <button 
              disabled={state.isProcessing || !state.image}
              onClick={startOCR}
              className="w-full py-4 bg-[#6750A4] text-white rounded-full font-bold m3-elevation-2 hover:bg-[#5E4794] active:scale-95 transition-all disabled:opacity-50 disabled:active:scale-100 flex items-center justify-center gap-2"
            >
              {state.isProcessing ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  <Icons.Scan />
                  Extract Text
                </>
              )}
            </button>
          </div>
        </section>

        {/* Results Section */}
        {state.error && (
          <div className="bg-red-50 text-red-600 p-4 rounded-2xl border border-red-200 text-sm flex items-center gap-3">
            <div className="bg-red-100 p-1 rounded-full">⚠️</div>
            {state.error}
          </div>
        )}

        {(state.extractedText || state.isProcessing) && (
          <section className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between px-1">
              <h2 className="text-lg font-bold text-[#1C1B1F]">Extracted Result</h2>
              <div className="flex gap-2">
                <button 
                  onClick={copyToClipboard}
                  className="p-2 text-[#6750A4] hover:bg-[#6750A4]/10 rounded-full"
                  title="Copy text"
                >
                  <Icons.Copy />
                </button>
                <button 
                  onClick={() => dispatch({ type: OCRActionType.SET_TEXT, payload: '' })}
                  className="p-2 text-red-500 hover:bg-red-50 rounded-full"
                  title="Clear"
                >
                  <Icons.Trash />
                </button>
              </div>
            </div>

            <textarea 
              value={state.extractedText}
              readOnly={state.isProcessing}
              onChange={(e) => dispatch({ type: OCRActionType.SET_TEXT, payload: e.target.value })}
              placeholder={state.isProcessing ? "Analyzing image..." : "Extracted text will appear here."}
              className="w-full min-h-[300px] p-5 bg-[#F7F2FA] rounded-3xl border border-[#79747E] focus:outline-none focus:ring-2 focus:ring-[#6750A4] text-sm leading-relaxed text-[#49454F] resize-none"
            />

            <div className="flex flex-col gap-3">
              <button 
                onClick={() => generatePDF(state.extractedText)}
                disabled={!state.extractedText}
                className="flex items-center justify-center gap-2 w-full py-4 border-2 border-[#6750A4] text-[#6750A4] rounded-full font-bold hover:bg-[#6750A4]/5 transition-colors disabled:opacity-30"
              >
                <Icons.FilePdf />
                Convert to PDF
              </button>
              <button 
                onClick={() => shareText(state.extractedText)}
                disabled={!state.extractedText}
                className="flex items-center justify-center gap-2 w-full py-4 bg-[#E8DEF8] text-[#1D192B] rounded-full font-bold hover:bg-[#DED2F1] transition-colors disabled:opacity-30"
              >
                <Icons.Share />
                Share Text
              </button>
            </div>
          </section>
        )}
      </main>

      {/* Persistent Call-to-Action / Floating Status */}
      {state.isProcessing && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-[#1C1B1F] text-white px-6 py-3 rounded-full flex items-center gap-3 shadow-2xl z-50">
          <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
          <span className="text-sm font-medium">Scanning with Gemini AI...</span>
        </div>
      )}
    </div>
  );
};

export default App;

export interface OCRState {
  image: string | null;
  extractedText: string;
  summaryText: string | null;
  isProcessing: boolean;
  isSummarizing: boolean;
  error: string | null;
  language: string;
  autoDetect: boolean;
  history: ScanEntry[];
  activeTab: 'scan' | 'history';
}

export interface ScanEntry {
  id: string;
  timestamp: number;
  text: string;
  thumbnail: string;
}

export enum OCRActionType {
  SET_IMAGE = 'SET_IMAGE',
  SET_TEXT = 'SET_TEXT',
  SET_SUMMARY = 'SET_SUMMARY',
  SET_PROCESSING = 'SET_PROCESSING',
  SET_SUMMARIZING = 'SET_SUMMARIZING',
  SET_ERROR = 'SET_ERROR',
  SET_LANGUAGE = 'SET_LANGUAGE',
  TOGGLE_AUTO_DETECT = 'TOGGLE_AUTO_DETECT',
  ADD_TO_HISTORY = 'ADD_TO_HISTORY',
  DELETE_HISTORY_ITEM = 'DELETE_HISTORY_ITEM',
  SET_HISTORY = 'SET_HISTORY',
  SET_TAB = 'SET_TAB',
  CLEAR_ALL = 'CLEAR_ALL'
}

export type OCRAction =
  | { type: OCRActionType.SET_IMAGE; payload: string | null }
  | { type: OCRActionType.SET_TEXT; payload: string }
  | { type: OCRActionType.SET_SUMMARY; payload: string | null }
  | { type: OCRActionType.SET_PROCESSING; payload: boolean }
  | { type: OCRActionType.SET_SUMMARIZING; payload: boolean }
  | { type: OCRActionType.SET_ERROR; payload: string | null }
  | { type: OCRActionType.SET_LANGUAGE; payload: string }
  | { type: OCRActionType.TOGGLE_AUTO_DETECT }
  | { type: OCRActionType.ADD_TO_HISTORY; payload: ScanEntry }
  | { type: OCRActionType.DELETE_HISTORY_ITEM; payload: string }
  | { type: OCRActionType.SET_HISTORY; payload: ScanEntry[] }
  | { type: OCRActionType.SET_TAB; payload: 'scan' | 'history' }
  | { type: OCRActionType.CLEAR_ALL };

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const performOCR = async (base64Image: string, language: string = 'auto'): Promise<string> => {
  const base64Data = base64Image.split(',')[1];

  const prompt = language === 'auto' 
    ? "Perform high-accuracy OCR on this image. Extract all readable text and maintain its structural formatting (paragraphs, lists, headings). If the text is in multiple languages, extract all of them."
    : `Perform high-accuracy OCR on this image, specifically focusing on ${language} text. Extract all readable text and maintain its structural formatting.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'image/png' } },
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1,
      }
    });

    return response.text || "No text could be extracted.";
  } catch (error) {
    console.error("OCR Service Error:", error);
    throw new Error("Failed to process image. Please check your internet connection.");
  }
};

export const summarizeText = async (text: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Please provide a concise summary of the following extracted text. Use bullet points if appropriate:\n\n${text}`,
      config: {
        temperature: 0.5,
      }
    });
    return response.text || "Could not generate summary.";
  } catch (error) {
    console.error("Summary Service Error:", error);
    throw new Error("Failed to generate summary.");
  }
};

