import React, { useReducer, useCallback, useRef, useEffect } from 'react';
import { OCRState, OCRActionType, OCRAction, ScanEntry } from './types';
import { performOCR, summarizeText } from './services/geminiService';
import { generatePDF, shareText } from './services/pdfService';
import { LANGUAGES, Icons } from './constants';

const initialState: OCRState = {
  image: null,
  extractedText: '',
  summaryText: null,
  isProcessing: false,
  isSummarizing: false,
  error: null,
  language: 'auto',
  autoDetect: true,
  history: [],
  activeTab: 'scan'
};

const STORAGE_KEY = 'smart_ocr_history_v1';

function ocrReducer(state: OCRState, action: OCRAction): OCRState {
  switch (action.type) {
    case OCRActionType.SET_TAB:
      return { ...state, activeTab: action.payload };
    case OCRActionType.SET_IMAGE:
      return { ...state, image: action.payload, extractedText: '', summaryText: null, error: null };
    case OCRActionType.SET_TEXT:
      return { ...state, extractedText: action.payload, isProcessing: false };
    case OCRActionType.SET_SUMMARY:
      return { ...state, summaryText: action.payload, isSummarizing: false };
    case OCRActionType.SET_PROCESSING:
      return { ...state, isProcessing: action.payload };
    case OCRActionType.SET_SUMMARIZING:
      return { ...state, isSummarizing: action.payload };
    case OCRActionType.SET_ERROR:
      return { ...state, error: action.payload, isProcessing: false, isSummarizing: false };
    case OCRActionType.SET_LANGUAGE:
      return { ...state, language: action.payload };
    case OCRActionType.TOGGLE_AUTO_DETECT:
      return { ...state, autoDetect: !state.autoDetect };
    case OCRActionType.SET_HISTORY:
      return { ...state, history: action.payload };
    case OCRActionType.ADD_TO_HISTORY:
      const newHistory = [action.payload, ...state.history].slice(0, 50);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newHistory));
      return { ...state, history: newHistory };
    case OCRActionType.DELETE_HISTORY_ITEM:
      const filtered = state.history.filter(item => item.id !== action.payload);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));
      return { ...state, history: filtered };
    case OCRActionType.CLEAR_ALL:
      return { ...initialState, history: state.history, activeTab: state.activeTab };
    default:
      return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(ocrReducer, initialState);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  // Load History from Local Storage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        dispatch({ type: OCRActionType.SET_HISTORY, payload: JSON.parse(saved) });
      } catch (e) {
        console.error("Failed to parse history", e);
      }
    }
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        dispatch({ type: OCRActionType.SET_IMAGE, payload: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const startOCR = async () => {
    if (!state.image) return;

    dispatch({ type: OCRActionType.SET_PROCESSING, payload: true });
    try {
      const result = await performOCR(state.image, state.language);
      dispatch({ type: OCRActionType.SET_TEXT, payload: result });

      // Save to history automatically
      const newEntry: ScanEntry = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        text: result,
        thumbnail: state.image
      };
      dispatch({ type: OCRActionType.ADD_TO_HISTORY, payload: newEntry });
    } catch (err: any) {
      dispatch({ type: OCRActionType.SET_ERROR, payload: err.message });
    }
  };

  const handleSummarize = async () => {
    if (!state.extractedText) return;
    dispatch({ type: OCRActionType.SET_SUMMARIZING, payload: true });
    try {
      const summary = await summarizeText(state.extractedText);
      dispatch({ type: OCRActionType.SET_SUMMARY, payload: summary });
    } catch (err: any) {
      dispatch({ type: OCRActionType.SET_ERROR, payload: err.message });
    }
  };

  const copyToClipboard = async (text: string) => {
    await navigator.clipboard.writeText(text);
  };

