    <div className="min-h-screen flex flex-col max-w-lg mx-auto bg-white shadow-xl relative overflow-hidden">
      {/* Top App Bar */}
      <header className="sticky top-0 z-50 bg-[#6750A4] text-white p-4 flex items-center justify-between m3-elevation-2 rounded-b-xl">
        <div className="flex items-center gap-3">
          <Icons.Scan />
          <h1 className="text-xl font-medium tracking-tight">Smart OCR Pro</h1>
        </div>
        <div className="flex gap-2">
          <button className="p-2 hover:bg-white/10 rounded-full transition-colors"><Icons.Help /></button>
          <button className="p-2 hover:bg-white/10 rounded-full transition-colors"><Icons.Settings /></button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-6 pb-24 bg-[#F7F2FA]">
        {state.activeTab === 'scan' ? (
