                >
                  <Icons.Camera />
                  <span className="text-sm font-semibold">Camera</span>
                </button>
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="flex flex-col items-center justify-center p-6 bg-[#EADDFF] text-[#21005D] rounded-[28px] gap-2 hover:bg-[#D0BCFF] transition-all m3-elevation-1 active:scale-95"
                >
                  <Icons.Gallery />
                  <span className="text-sm font-semibold">Gallery</span>
                </button>
              </div>

              <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} onChange={handleFileChange} className="hidden" />
              <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} className="hidden" />

              {state.image ? (
                <div className="relative group animate-in zoom-in-95 duration-200">
                  <div className="rounded-[28px] overflow-hidden bg-slate-100 border-2 border-dashed border-[#6750A4]/30 aspect-video flex items-center justify-center m3-elevation-1">
                    <img src={state.image} alt="Captured" className="w-full h-full object-contain" />
                  </div>
                  <button 
                    onClick={() => dispatch({ type: OCRActionType.SET_IMAGE, payload: null })}
                    className="absolute top-2 right-2 p-2 bg-white/90 rounded-full text-red-500 shadow-md active:bg-red-100"
                  >
                    <Icons.Trash />
                  </button>
                </div>
              ) : (
                <div className="rounded-[28px] overflow-hidden bg-white border-2 border-dashed border-slate-200 aspect-video flex flex-col items-center justify-center text-slate-400 gap-2 m3-elevation-1">
                  <div className="opacity-40 scale-150 mb-2"><Icons.Gallery /></div>
