              <div className="flex items-center justify-between mb-2">
                <h2 className="text-sm font-bold text-[#49454F] uppercase tracking-wider">Scan Config</h2>
                <div className="bg-[#6750A4]/10 px-3 py-1 rounded-full text-[10px] font-bold text-[#6750A4] uppercase">AI Enabled</div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-medium text-[#1C1B1F]">Auto-detect Language</label>
