                    type="checkbox" 
                    checked={state.autoDetect}
                    onChange={() => dispatch({ type: OCRActionType.TOGGLE_AUTO_DETECT })}
                    className="w-10 h-6 bg-[#E7E0EC] checked:bg-[#6750A4] rounded-full appearance-none transition-all cursor-pointer relative after:content-[''] after:absolute after:top-1 after:left-1 after:bg-white after:w-4 after:h-4 after:rounded-full after:transition-all checked:after:translate-x-4 m3-elevation-1"
                  />
                </div>

                {!state.autoDetect && (
                  <div className="flex flex-col gap-1 animate-in slide-in-from-top-2 duration-200">
                    <select 
                      value={state.language}
                      onChange={(e) => dispatch({ type: OCRActionType.SET_LANGUAGE, payload: e.target.value })}
                      className="w-full p-3 bg-white rounded-xl border border-[#79747E] text-sm focus:ring-2 focus:ring-[#6750A4] appearance-none"
                    >
                      {LANGUAGES.map(lang => (
                        <option key={lang.code} value={lang.code}>{lang.name}</option>
                      ))}
                    </select>
                  </div>
                )}

                <button 
                  disabled={state.isProcessing || !state.image}
                  onClick={startOCR}
                  className="w-full py-4 bg-[#6750A4] text-white rounded-full font-bold m3-elevation-2 hover:bg-[#5E4794] active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {state.isProcessing ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : "Start Extraction"}
                </button>
              </div>
            </section>

            {/* AI Results */}
            {state.extractedText && (
              <section className="space-y-4 animate-in slide-in-from-bottom-8 duration-500">
                <div className="bg-white rounded-[28px] overflow-hidden m3-elevation-1">
                  <div className="p-4 bg-[#F3EDF7] border-b border-[#CAC4D0] flex items-center justify-between">
                    <span className="text-sm font-bold text-[#6750A4]">Extracted Text</span>
                    <button onClick={() => copyToClipboard(state.extractedText)} className="p-2 text-[#6750A4] hover:bg-[#6750A4]/10 rounded-full"><Icons.Copy /></button>
                  </div>
                  <textarea 
                    value={state.extractedText}
                    onChange={(e) => dispatch({ type: OCRActionType.SET_TEXT, payload: e.target.value })}
                    className="w-full min-h-[250px] p-5 focus:outline-none text-sm leading-relaxed text-[#49454F] bg-transparent resize-none"
                  />
                </div>

                {/* AI Summary Tool */}
                {!state.summaryText ? (
                  <button 
                    onClick={handleSummarize}
                    disabled={state.isSummarizing}
                    className="w-full py-4 border-2 border-[#6750A4] text-[#6750A4] rounded-full font-bold flex items-center justify-center gap-2 hover:bg-[#6750A4]/5 active:scale-95 transition-all"
                  >
                    {state.isSummarizing ? <div className="w-5 h-5 border-2 border-[#6750A4]/30 border-t-[#6750A4] rounded-full animate-spin" /> : <><Icons.Sparkles /> Generate AI Summary</>}
                  </button>
