                  <div className="bg-[#EADDFF] p-5 rounded-[28px] m3-elevation-1 space-y-3 animate-in fade-in zoom-in-95">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2 text-[#21005D]">
                        <Icons.Sparkles />
