import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const performOCR = async (base64Image: string, language: string = 'auto'): Promise<string> => {
  const base64Data = base64Image.split(',')[1];
  const prompt = language === 'auto' 
    ? "Perform high-accuracy OCR. Extract all readable text with structural formatting."
    : `Perform high-accuracy OCR focusing on ${language} text.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'image/png' } },
          { text: prompt }
        ]
      },
      config: { temperature: 0.1 }
    });
    return response.text || "No text found.";
  } catch (error) {
    throw new Error("OCR failed. Check connection.");
  }
};

export const summarizeText = async (text: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Summarize this text in bullet points:\n\n${text}`,
    config: { temperature: 0.4 }
  });
  return response.text || "Summary failed.";
};

export const translateText = async (text: string, targetLang: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Translate the following text into ${targetLang}. Only return the translation:\n\n${text}`,
    config: { temperature: 0.3 }
  });
  return response.text || "Translation failed.";
};

import React, { useReducer, useRef, useEffect, useState } from 'react';
import { OCRState, OCRActionType, OCRAction, ScanEntry } from './types';
import { performOCR, summarizeText, translateText } from './services/geminiService';
import { generatePDF, shareText } from './services/pdfService';
import { LANGUAGES, Icons } from './constants';

const initialState: OCRState = {
  image: null,
  extractedText: '',
  summaryText: null,
  isProcessing: false,
  isSummarizing: false,
  error: null,
  language: 'auto',
  autoDetect: true,
  history: [],
  activeTab: 'scan'
};

const STORAGE_KEY = 'ocr_pro_data';

function ocrReducer(state: OCRState, action: OCRAction): OCRState {
  switch (action.type) {
    case OCRActionType.SET_TAB: return { ...state, activeTab: action.payload };
    case OCRActionType.SET_IMAGE: return { ...state, image: action.payload, extractedText: '', summaryText: null, error: null };
    case OCRActionType.SET_TEXT: return { ...state, extractedText: action.payload, isProcessing: false };
    case OCRActionType.SET_SUMMARY: return { ...state, summaryText: action.payload, isSummarizing: false };
    case OCRActionType.SET_PROCESSING: return { ...state, isProcessing: action.payload };
    case OCRActionType.SET_SUMMARIZING: return { ...state, isSummarizing: action.payload };
    case OCRActionType.SET_ERROR: return { ...state, error: action.payload, isProcessing: false, isSummarizing: false };
    case OCRActionType.SET_LANGUAGE: return { ...state, language: action.payload };
    case OCRActionType.TOGGLE_AUTO_DETECT: return { ...state, autoDetect: !state.autoDetect };
    case OCRActionType.SET_HISTORY: return { ...state, history: action.payload };
    case OCRActionType.ADD_TO_HISTORY:
      const h = [action.payload, ...state.history].slice(0, 30);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(h));
      return { ...state, history: h };
    case OCRActionType.DELETE_HISTORY_ITEM:
      const f = state.history.filter(i => i.id !== action.payload);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(f));
      return { ...state, history: f };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(ocrReducer, initialState);
  const [isTranslating, setIsTranslating] = useState(false);
  const camRef = useRef<HTMLInputElement>(null);
  const galRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) dispatch({ type: OCRActionType.SET_HISTORY, payload: JSON.parse(saved) });
  }, []);

  const onFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (f) {
      const r = new FileReader();
      r.onload = () => dispatch({ type: OCRActionType.SET_IMAGE, payload: r.result as string });
      r.readAsDataURL(f);
    }
  };

  const handleOCR = async () => {
    if (!state.image) return;
    dispatch({ type: OCRActionType.SET_PROCESSING, payload: true });
    try {
      const res = await performOCR(state.image, state.language);
      dispatch({ type: OCRActionType.SET_TEXT, payload: res });
      dispatch({ type: OCRActionType.ADD_TO_HISTORY, payload: { id: Date.now().toString(), timestamp: Date.now(), text: res, thumbnail: state.image } });
    } catch (e: any) { dispatch({ type: OCRActionType.SET_ERROR, payload: e.message }); }
  };

  const handleTranslate = async () => {
    if (!state.extractedText) return;
    setIsTranslating(true);
    try {
      const t = await translateText(state.extractedText, state.language);
      dispatch({ type: OCRActionType.SET_TEXT, payload: t });
    } catch (e: any) { dispatch({ type: OCRActionType.SET_ERROR, payload: "Translation failed" }); }
    finally { setIsTranslating(false); }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-lg mx-auto bg-[#F7F2FA] shadow-2xl relative overflow-hidden font-sans">
      <header className="sticky top-0 z-50 bg-[#6750A4] text-white p-4 flex items-center justify-between m3-elevation-2">
        <div className="flex items-center gap-3"><Icons.Scan /> <h1 className="text-xl font-medium">Smart OCR Pro</h1></div>
        <div className="flex gap-1"><button className="p-2"><Icons.Settings /></button></div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-6 pb-24">
        {state.activeTab === 'scan' ? (
          <div className="space-y-6 animate-in fade-in duration-300">
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => camRef.current?.click()} className="flex flex-col items-center p-6 bg-[#EADDFF] text-[#21005D] rounded-[28px] gap-2 m3-elevation-1 active:scale-95 transition-all">
                <Icons.Camera /> <span className="text-xs font-bold uppercase">Camera</span>
              </button>
              <button onClick={() => galRef.current?.click()} className="flex flex-col items-center p-6 bg-[#EADDFF] text-[#21005D] rounded-[28px] gap-2 m3-elevation-1 active:scale-95 transition-all">
                <Icons.Gallery /> <span className="text-xs font-bold uppercase">Gallery</span>
              </button>
            </div>

            <input type="file" accept="image/*" capture="environment" ref={camRef} onChange={onFile} className="hidden" />
            <input type="file" accept="image/*" ref={galRef} onChange={onFile} className="hidden" />

            <div className="bg-white rounded-[28px] p-4 m3-elevation-1 space-y-4">
              <div className="aspect-video bg-[#F3EDF7] rounded-2xl overflow-hidden flex items-center justify-center border-2 border-dashed border-[#CAC4D0]">
                {state.image ? <img src={state.image} className="h-full object-contain" /> : <div className="text-slate-400 opacity-50"><Icons.Gallery /></div>}
              </div>

              <div className="flex items-center justify-between">
                <label className="text-sm font-bold text-[#49454F]">AUTO-DETECT</label>
                <input type="checkbox" checked={state.autoDetect} onChange={() => dispatch({ type: OCRActionType.TOGGLE_AUTO_DETECT })} className="w-10 h-6 bg-[#E7E0EC] checked:bg-[#6750A4] rounded-full appearance-none cursor-pointer relative after:absolute after:top-1 after:left-1 after:bg-white after:w-4 after:h-4 after:rounded-full checked:after:translate-x-4 transition-all" />
              </div>

              {!state.autoDetect && (
                <select value={state.language} onChange={(e) => dispatch({ type: OCRActionType.SET_LANGUAGE, payload: e.target.value })} className="w-full p-3 border border-[#79747E] rounded-xl text-sm">
                  {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                </select>
              )}

              <button disabled={state.isProcessing || !state.image} onClick={handleOCR} className="w-full py-4 bg-[#6750A4] text-white rounded-full font-bold m3-elevation-2 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-2">
                {state.isProcessing ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : "EXTRACT TEXT"}
              </button>
            </div>

            {state.extractedText && (
              <div className="bg-white rounded-[28px] p-4 m3-elevation-1 space-y-4 animate-in slide-in-from-bottom-4">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold text-[#6750A4]">RESULT</span>
                  <div className="flex gap-2">
                    <button onClick={() => handleTranslate()} className="p-2 text-[#6750A4]">{isTranslating ? '...' : <Icons.Sparkles />}</button>
                    <button onClick={() => shareText(state.extractedText)} className="p-2 text-[#6750A4]"><Icons.Share /></button>
                  </div>
                </div>
                <textarea value={state.extractedText} onChange={e => dispatch({type: OCRActionType.SET_TEXT, payload: e.target.value})} className="w-full min-h-[200px] text-sm leading-relaxed p-0 border-none focus:ring-0 text-[#49454F]" />
                <div className="grid grid-cols-2 gap-3 pt-4 border-t border-[#CAC4D0]">
                  <button onClick={() => generatePDF(state.extractedText)} className="py-3 bg-[#1C1B1F] text-white rounded-full text-xs font-bold">PDF</button>
                  <button onClick={() => navigator.clipboard.writeText(state.extractedText)} className="py-3 bg-[#E8DEF8] text-[#1D192B] rounded-full text-xs font-bold">COPY</button>
                </div>
              </div>
            )}
          </div>
        ) : (
          <div className="space-y-4 animate-in fade-in">
            <h2 className="text-lg font-bold px-2">Recent Scans</h2>
            {state.history.map(i => (
              <div key={i.id} className="bg-white p-3 rounded-2xl flex gap-3 m3-elevation-1">
                <img src={i.thumbnail} className="w-16 h-16 rounded-lg object-cover bg-slate-100" />
                <div className="flex-1">
                  <p className="text-[10px] font-bold text-[#6750A4]">{new Date(i.timestamp).toLocaleDateString()}</p>
                  <p className="text-xs text-[#1C1B1F] line-clamp-1 mt-1 font-medium">{i.text}</p>
                  <div className="flex gap-4 mt-2">
                    <button onClick={() => { dispatch({type: OCRActionType.SET_IMAGE, payload: i.thumbnail}); dispatch({type: OCRActionType.SET_TEXT, payload: i.text}); dispatch({type: OCRActionType.SET_TAB, payload: 'scan'}); }} className="text-[10px] font-bold text-[#6750A4]">OPEN</button>
                    <button onClick={() => dispatch({type: OCRActionType.DELETE_HISTORY_ITEM, payload: i.id})} className="text-[10px] font-bold text-red-500">DELETE</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-[#F3EDF7] flex justify-around p-3 border-t rounded-t-3xl m3-elevation-2">
        <button onClick={() => dispatch({type: OCRActionType.SET_TAB, payload: 'scan'})} className={`flex flex-col items-center gap-1 min-w-[64px] ${state.activeTab === 'scan' ? 'text-[#6750A4]' : 'text-slate-500'}`}>
          <div className={`p-1 px-5 rounded-full ${state.activeTab === 'scan' ? 'bg-[#E8DEF8]' : ''}`}><Icons.Home /></div>
          <span className="text-[10px] font-bold uppercase">Scanner</span>
