        <button onClick={() => dispatch({type: OCRActionType.SET_TAB, payload: 'history'})} className={`flex flex-col items-center gap-1 min-w-[64px] ${state.activeTab === 'history' ? 'text-[#6750A4]' : 'text-slate-500'}`}>
