export default function App() {
  const [view, setView] = useState<'landing' | 'dashboard'>('landing');
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'dark') {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
    setIsDark(!isDark);
    if (!isDark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  const scrollToSection = (id: string) => {
    if (view !== 'landing') {
      setView('landing');
      setTimeout(() => {
        const element = document.getElementById(id);
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 100);
      return;
    }
    const element = document.getElementById(id);
    if (element) element.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <>
      {view === 'landing' ? (
        <>
          <Navbar isDark={isDark} toggleTheme={toggleTheme} scrollToSection={scrollToSection} onStart={() => setView('dashboard')} />
          <main>
            <HeroSection onStart={() => setView('dashboard')} />
            <FeaturesSection />
            <Section className="bg-gray-900 text-white">
                <div className="container mx-auto text-center">
                    <h2 className="text-3xl font-bold mb-6">Ready to Start?</h2>
                    <button onClick={() => setView('dashboard')} className="px-8 py-4 bg-blue-600 hover:bg-blue-700 rounded-full font-bold">Launch Dashboard</button>
                </div>
            </Section>
          </main>
          <footer className="bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800 pt-16 pb-8">
             <div className="container mx-auto px-6 text-center text-gray-500 text-sm">
                <p>© 2026 MindCraft Inc.</p>
             </div>
          </footer>
        </>
      ) : (
        <Dashboard onBack={() => setView('landing')} isDark={isDark} />
      )}
    </>
  );
}

