                        <span className="text-purple-600">Q{qIndex + 1}.</span> {q.question}
                      </h3>
                      <div className="space-y-3">
                        {q.options.map((opt, oIndex) => {
                          const isSelected = answers[qIndex] === oIndex;
                          const isCorrect = q.correctAnswer === oIndex;
                          let btnClass = isDark ? "bg-gray-800 hover:bg-gray-700" : "bg-gray-50 hover:bg-gray-100";

                          if (showResults) {
                            if (isCorrect) btnClass = "bg-green-100 border-green-500 text-green-900 dark:bg-green-900/40 dark:text-green-100 dark:border-green-500";
                            else if (isSelected && !isCorrect) btnClass = "bg-red-100 border-red-500 text-red-900 dark:bg-red-900/40 dark:text-red-100 dark:border-red-500";
                          } else if (isSelected) {
                            btnClass = "bg-purple-100 border-purple-500 text-purple-900 dark:bg-purple-900/40 dark:text-purple-100 dark:border-purple-500";
                          }

                          return (
                            <button 
                              key={oIndex}
                              disabled={showResults}
                              onClick={() => setAnswers({...answers, [qIndex]: oIndex})}
                              className={`w-full text-left p-4 rounded-xl border border-transparent transition-all ${btnClass}`}
                            >
                              {opt}
                            </button>
                          );
                        })}
                      </div>
                      {showResults && (
                        <div className="mt-4 p-4 bg-gray-50 dark:bg-gray-800 rounded-lg text-sm opacity-90">
                          <span className="font-bold">Explanation:</span> {q.explanation}
                        </div>
                      )}
                    </div>
                  ))}

                  {!showResults && (
                    <button 
                      onClick={() => setShowResults(true)}
                      className="w-full py-4 bg-gray-900 dark:bg-white dark:text-gray-900 text-white font-bold rounded-xl"
                    >
                      Submit Answers
                    </button>
                  )}
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

