const useToast = () => {
  const [toast, setToast] = useState<{ isVisible: boolean; type: 'success' | 'loading' | 'info' | 'error';jq: string; message: string; progress: number; }>({ isVisible: false, type: 'success', jq: '', message: '', progress: 0 });
  const showToast = (message: string, type: 'success' | 'loading' | 'info' | 'error' = 'success') => { 
      setToast({ isVisible: true, type, message, progress: 0, jq: '' }); 
      if (type !== 'loading') { setTimeout(() => setToast(prev => ({ ...prev, isVisible: false })), 4000); } 
  };
  return { toast, showToast, setToast };
};

const Toast = ({ isVisible, message, type, progress, onClose }: any) => {
