const AIDemoSection = () => {
  const [messages, setMessages] = useState<any[]>([
    { role: 'ai', text: 'Hi there! I am your personal MindCraft tutor. How can I help you study today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async (text: string = input) => {
    if (!text.trim()) return;
    const userMsg = { role: 'user', text: text };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    // Simulate AI thinking and response
    await new Promise(resolve => setTimeout(resolve, 1500));

    let aiResponseText = "That's an excellent topic! I can create a summarized study guide, generate flashcards, or quiz you on it. Download the MindCraft app to get started!";

    if (text.toLowerCase().includes('quantum')) {
      aiResponseText = "Quantum Entanglement is spooky action at a distance! To fully master this, I can generate a 10-question quiz for you. Want to try it in the app?";
    } else if (text.toLowerCase().includes('gatsby')) {
      aiResponseText = "The Great Gatsby is a classic! I can outline the key themes of decadence and idealism for your essay. Check the full app for the essay writer tool.";
    }

    setMessages(prev => [...prev, { role: 'ai', text: aiResponseText }]);
    setIsTyping(false);
  };

  return (
    <section className="py-24 bg-white dark:bg-gray-950 overflow-hidden">
      <div className="container mx-auto px-6">
        <div className="grid lg:grid-cols-2 gap-16 items-center">
          <div className="order-2 lg:order-1">
             <div className="relative">
                <div className="absolute inset-0 bg-gradient-to-tr from-blue-500 to-purple-500 rounded-[2.5rem] blur-xl opacity-20 transform -rotate-3"></div>
                <div className="relative bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-[2.5rem] shadow-2xl overflow-hidden h-[600px] flex flex-col">
