                   <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex items-center justify-between bg-white/80 dark:bg-gray-900/80 backdrop-blur-md z-10 sticky top-0">
                     <div className="flex items-center gap-4">
                       <div className="relative">
                         <div className="w-12 h-12 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white shadow-lg">
                           <Sparkles size={20}/>
                         </div>
                         <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-gray-900 rounded-full"></div>
                       </div>
                       <div>
                         <div className="font-bold text-lg text-gray-900 dark:text-white">MindCraft AI</div>
                         <div className="text-xs text-blue-500 font-medium">Online • Active Now</div>
                       </div>
                     </div>
                     <button className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><Menu size={20} className="text-gray-500"/></button>
                   </div>

                   {/* Chat Area */}
                   <div ref={scrollRef} className="flex-1 p-6 overflow-y-auto space-y-6 bg-gray-50/50 dark:bg-gray-900/50">
                     {messages.map((m, i) => (
                       <motion.div 
                         initial={{ opacity: 0, y: 20, scale: 0.95 }} 
                         animate={{ opacity: 1, y: 0, scale: 1 }}
                         key={i} 
                         className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
                       >
                         {m.role === 'ai' && (
                           <div className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex-shrink-0 flex items-center justify-center text-white text-xs mr-3 mt-1 shadow-sm">AI</div>
                         )}
                         <div className={`max-w-[80%] p-4 rounded-2xl shadow-sm text-sm leading-relaxed ${m.role === 'user' ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 border border-gray-100 dark:border-gray-700 rounded-bl-none'}`}>
                           {m.text}
