                         {m.role === 'user' && (
                           <div className="w-8 h-8 rounded-full bg-gray-300 dark:bg-gray-700 flex-shrink-0 flex items-center justify-center text-gray-600 dark:text-gray-300 text-xs ml-3 mt-1">Me</div>
