                     <button key={q} onClick={() => handleSend(q)} className="whitespace-nowrap px-5 py-3 rounded-xl bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-sm font-medium hover:border-blue-500 hover:text-blue-600 dark:hover:text-blue-400 transition-all text-gray-700 dark:text-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500">
