                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="flex items-start gap-3">
                      <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg text-green-600"><CheckCircle size={20}/></div>
                      <div>
                        <h4 className="font-bold text-gray-900 dark:text-white">24/7 Availability</h4>
