const useToast = () => {
  const [toast, setToast] = useState<{ isVisible: boolean; type: 'success' | 'loading' | 'info' | 'error'; message: string; progress: number; }>({ isVisible: false, type: 'success', message: '', progress: 0 });
  const showToast = (message: string, type: 'success' | 'loading' | 'info' | 'error' = 'success') => { 
      setToast({ isVisible: true, type, message, progress: 0 }); 
      if (type !== 'loading') { setTimeout(() => setToast(prev => ({ ...prev, isVisible: false })), 4000); } 
  };
  return { toast, showToast, setToast };
};

const Toast = ({ isVisible, message, type, progress, onClose }: any) => {
  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div 
          initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 20 }}
          role="alert"
          className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] bg-gray-900 dark:bg-gray-800 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 min-w-[300px]"
        >
          <div className={`p-2 rounded-full ${type === 'loading' ? 'bg-blue-500/20 text-blue-400' : type === 'error' ? 'bg-red-500/20 text-red-400' : 'bg-green-500/20 text-green-400'}`}>
            {type === 'loading' ? <Sparkles className="animate-spin" size={20}/> : type === 'error' ? <X size={20}/> : <Check size={20}/>}
          </div>
          <div className="flex-1">
            <p className="font-medium text-sm">{message}</p>
            {type === 'loading' && (
              <div className="h-1 w-full bg-gray-800 rounded-full mt-2 overflow-hidden">
                <motion.div className="h-full bg-blue-500" initial={{ width: 0 }} animate={{ width: `${progress}%` }} />
              </div>
            )}
          </div>
          <button onClick={onClose} aria-label="Close notification"><X size={16} className="opacity-50 hover:opacity-100"/></button>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

const ScrollToTop = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    const toggleVisibility = () => {
      if (window.scrollY > 300) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };
    window.addEventListener("scroll", toggleVisibility);
    return () => window.removeEventListener("scroll", toggleVisibility);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: "smooth"
    });
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 0, scale: 0.5, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.5, y: 20 }}
          className="fixed bottom-8 right-8 z-[90]"
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
        >
          <button
            onClick={scrollToTop}
            className="group relative flex items-center justify-center w-14 h-14 bg-white dark:bg-gray-800 rounded-2xl shadow-xl border border-blue-100 dark:border-gray-700 hover:border-blue-500 dark:hover:border-blue-500 transition-all focus:outline-none focus:ring-4 focus:ring-blue-500/30"
            aria-label="Scroll to top"
          >
            <MindCraftLogo className={`w-8 h-8 transition-opacity duration-300 ${isHovered ? 'opacity-0' : 'opacity-100'}`} />
            <ArrowUp className={`w-6 h-6 text-blue-600 absolute transition-opacity duration-300 transform ${isHovered ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2'}`} />

            {/* Tooltip */}
            <AnimatePresence>
              {isHovered && (
                <motion.div
                  initial={{ opacity: 0, x: 20, scale: 0.8 }}
                  animate={{ opacity: 1, x: -70, scale: 1 }}
                  exit={{ opacity: 0, x: 20, scale: 0.8 }}
                  className="absolute right-0 bg-gray-900 text-white px-3 py-1.5 rounded-lg text-xs font-bold whitespace-nowrap shadow-lg pointer-events-none"
                >
                  Back to Top 🚀
                </motion.div>
              )}
            </AnimatePresence>
          </button>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

