const AIDemoSection = () => {
  const [messages, setMessages] = useState<any[]>([
    { role: 'ai', text: 'Hi! I am your MindCraft AI tutor. What are we studying today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    // Simulate AI thinking and response
    await new Promise(resolve => setTimeout(resolve, 1500));

    let aiResponseText = "That's a fascinating topic! I can help you break it down, create a study schedule for it, or generate a quiz. Download the full app to get started!";

    if (userMsg.text.toLowerCase().includes('quantum')) {
      aiResponseText = "Quantum Entanglement is a phenomenon where particles become correlated in such a way that the quantum state of each particle cannot be described independently. Want a quiz on this?";
    } else if (userMsg.text.toLowerCase().includes('gatsby')) {
      aiResponseText = "The Great Gatsby explores themes of decadence, idealism, and excess. I can generate an essay outline for you in the full app!";
    }

    setMessages(prev => [...prev, { role: 'ai', text: aiResponseText }]);
    setIsTyping(false);
  };

  return (
    <section className="py-24 bg-white dark:bg-gray-950 overflow-hidden">
      <div className="container mx-auto px-6">
        <div className="grid lg:grid-cols-2 gap-16 items-center">
          <div>
             <h2 className="text-3xl lg:text-4xl font-bold mb-6 text-gray-900 dark:text-white">Ask Anything.<br/><span className="text-purple-600">Get Instant Answers.</span></h2>
             <p className="text-lg text-gray-500 mb-8">
               Stuck on a concept? Just ask. Our AI explains complex topics in simple terms, provides examples, and even helps you solve math problems.
             </p>
             <div className="flex flex-wrap gap-3">
               {['Explain Quantum Entanglement', 'Summarize The Great Gatsby', 'Calculus Derivatives'].map(q => (
                 <button key={q} onClick={() => setInput(q)} className="px-4 py-2 rounded-full bg-gray-100 dark:bg-gray-800 text-sm font-medium hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors text-gray-700 dark:text-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-500">
                   {q}
                 </button>
               ))}
             </div>
          </div>
          <div className="relative">
             <div className="absolute inset-0 bg-gradient-to-r from-blue-500 to-purple-500 rounded-3xl blur-2xl opacity-20 transform rotate-3"></div>
             <div className="relative bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-3xl shadow-2xl overflow-hidden h-[500px] flex flex-col">
                <div className="p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3 bg-gray-50/50 dark:bg-gray-900/50 backdrop-blur">
                  <div className="w-8 h-8 rounded-full bg-purple-600 flex items-center justify-center text-white"><Sparkles size={16}/></div>
                  <div className="font-bold text-gray-900 dark:text-white">MindCraft AI</div>
                </div>
                <div ref={scrollRef} className="flex-1 p-4 overflow-y-auto space-y-4 scroll-smooth">
                  {messages.map((m, i) => (
                    <motion.div 
                      initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
                      key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
                    >
                      <div className={`max-w-[80%] p-4 rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-200 rounded-tl-none'}`}>
                        {m.text}
                      </div>
                    </motion.div>
                  ))}
                  {isTyping && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex justify-start">
                      <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-2xl rounded-tl-none flex gap-1">
                        <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></span>
                        <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></span>
                        <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></span>
                      </div>
                    </motion.div>
                  )}
                </div>
                <div className="p-4 border-t border-gray-100 dark:border-gray-800 bg-white dark:bg-gray-900">
                  <div className="flex gap-2">
                    <input 
                      value={input}
                      onChange={(e) => setInput(e.target.value)}
                      placeholder="Type a question..."
                      className="flex-1 bg-gray-100 dark:bg-gray-800 border-none rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none text-gray-900 dark:text-white"
                      onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    />
                    <button onClick={handleSend} className="p-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" aria-label="Send message"><Send size={20}/></button>
                  </div>
                </div>
             </div>
          </div>
        </div>
      </div>
    </section>
  );
};

