export default function App() {
  const [view, setView] = useState<'landing' | 'dashboard'>('landing');
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const [selectedFeature, setSelectedFeature] = useState<any>(null);
  const [isDark, setIsDark] = useState(false);
  const { toast, showToast, setToast } = useToast();

  useEffect(() => {
    // Check system preference
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const savedTheme = localStorage.getItem('theme');

    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    } else {
      setIsDark(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const toggleTheme = () => {
    setIsDark(!isDark);
    if (!isDark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  const handleAuth = (data: any) => {
    setIsAuthOpen(false);
    showToast(`Welcome, ${data.name}!`, 'success');
    setUser(data);
    setView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setView('landing');
    showToast('Logged out successfully', 'info');
  };

  const handleDownload = () => {
    showToast('Starting download...', 'loading');
    let progress = 0;
    const interval = setInterval(() => {
      progress += 20;
      setToast(prev => ({ ...prev, progress }));
      if (progress >= 100) {
        clearInterval(interval);
        showToast('MindCraft APK Downloaded!', 'success');
        // Trigger actual download here if available
      }
    }, 200);
  };

  const onNavigate = (page: string) => {
    if (page === 'dashboard') {
       if (user) setView('dashboard');
       else {
         showToast('Please sign in first', 'info');
         setIsAuthOpen(true);
       }
    } else {
       setView('landing');
    }
  };

  return (
    <div className={`min-h-screen ${isDark ? 'dark' : ''} bg-white dark:bg-gray-950 text-gray-900 dark:text-white selection:bg-blue-500 selection:text-white transition-colors duration-300`}>
      <Navbar onLoginClick={() => setIsAuthOpen(true)} user={user} onLogoutClick={handleLogout} onNavigate={onNavigate} currentPage={view} isDark={isDark} toggleTheme={toggleTheme} />

      <main>
        {view === 'landing' ? (
          <>
            <HeroSection onDownloadClick={handleDownload} />
            <FeaturesSection onFeatureClick={setSelectedFeature} />
            <AIDemoSection />
            <RoadmapSection />
            <TestimonialsSection />
            <section className="py-20 px-4 md:px-6 bg-gray-50 dark:bg-gray-900">
              <div className="container mx-auto max-w-5xl">
                <div className="bg-gray-900 rounded-[2.5rem] border border-gray-800 p-8 md:p-16 relative overflow-hidden flex flex-col md:flex-row items-center justify-between gap-12 text-white shadow-2xl">
                  <div className="relative z-10 max-w-lg text-center md:text-left">
                    <h2 className="text-4xl md:text-5xl font-bold mb-6 leading-tight">Download the <br/> app now!</h2>
                    <p className="text-gray-400 text-lg mb-8 leading-relaxed">You’re just a step away from starting your smarter engineering journey.</p>
                    <div className="flex flex-col gap-6">
                      <button onClick={handleDownload} className="px-8 py-4 bg-blue-600 rounded-xl font-bold text-white hover:bg-blue-700 transition-all flex items-center justify-center gap-2 shadow-lg hover:-translate-y-1 focus:outline-none focus:ring-4 focus:ring-blue-500/50">
                        <Download size={22} /> Download APK Directly
                      </button>
                    </div>
                  </div>
                  <div className="relative z-10 flex-shrink-0">
                    <div className="relative w-[240px] h-[480px] bg-gray-800 rounded-[3rem] border-8 border-gray-700 shadow-2xl flex flex-col items-center justify-center p-6">
                      <div className="absolute top-0 w-32 h-6 bg-gray-700 rounded-b-xl"></div>
                      <div className="w-full h-full bg-white rounded-[2rem] flex flex-col items-center justify-center text-center p-6">
                        <p className="text-gray-500 font-medium mb-8">Scan QR to download</p>
                        <div className="bg-white p-2 rounded-xl border border-gray-200 mb-8">
                           <img src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=https://example.com" alt="QR Code" className="w-32 h-32"/>
                        </div>
                        <MindCraftLogo className="w-10 h-10" />
                      </div>
                    </div>
                  </div>
                  <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-blue-600/10 rounded-full blur-[120px] pointer-events-none"></div>
                </div>
              </div>
            </section>
          </>
        ) : (
          <UserDashboard user={user} onLogout={handleLogout} />
        )}
      </main>

      {view === 'landing' && <Footer showToast={showToast} onNavigate={onNavigate} />}

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onAuth={handleAuth} />
      <FeatureModal feature={selectedFeature} onClose={() => setSelectedFeature(null)} />
      <Toast {...toast} onClose={() => setToast(prev => ({...prev, isVisible: false}))} />
      <ScrollToTop />
      <PrepBot />
    </div>
  );
}

