const FloatingElement = ({ delay, xOffset, yOffset, icon: Icon, className, mouseX, mouseY, mouseFactor = 1 }: any) => {
  const xMouse = useTransform(mouseX, [-0.5, 0.5], [-30 * mouseFactor, 30 * mouseFactor]);
  const yMouse = useTransform(mouseY, [-0.5, 0.5], [-30 * mouseFactor, 30 * mouseFactor]);

  return (
    <motion.div
      style={{ x: xMouse, y: yMouse, zIndex: 30, left: '50%', top: '50%', position: 'absolute' }}
    >
      <motion.div
        initial={{ x: xOffset, y: yOffset, opacity: 0, scale: 0 }}
        animate={{ 
          y: [yOffset, yOffset - 15, yOffset + 15, yOffset],
          x: [xOffset, xOffset + 10, xOffset - 10, xOffset],
          rotate: [0, 5, -5, 0],
          opacity: 1,
          scale: 1
        }}
        transition={{ 
          duration: 8 + delay, 
          repeat: Infinity, 
          ease: "easeInOut",
          delay: delay * 0.5
        }}
        className={`ml-[-2rem] mt-[-2rem] p-4 rounded-2xl bg-white/90 dark:bg-gray-800/90 backdrop-blur-xl border shadow-xl ${className}`}
      >
        <Icon size={32} />
      </motion.div>
    </motion.div>
  );
};

