const FloatingElement = ({ delay, x, y, icon: Icon, className, mouseX, mouseY, depth = 1 }: any) => {
  // Parallax based on mouse
  const xMotion = useTransform(mouseX, [-0.5, 0.5], [-20 * depth, 20 * depth]);
  const yMotion = useTransform(mouseY, [-0.5, 0.5], [-20 * depth, 20 * depth]);
  const rotateMotion = useTransform(mouseX, [-0.5, 0.5], [-5 * depth, 5 * depth]);

  return (
    <motion.div
      style={{ 
        x: xMotion, 
        y: yMotion, 
        rotate: rotateMotion,
        zIndex: depth * 10, // Depth determines Z-index
        position: 'absolute', 
        left: '50%', 
        top: '50%' 
      }}
    >
      <motion.div
        initial={{ x, y, opacity: 0, scale: 0 }}
        animate={{ 
          y: [y, y - 10, y + 10, y],
          rotate: [0, 5, -5, 0],
          opacity: 1,
          scale: 1
        }}
        transition={{ 
          duration: 6 + delay, 
          repeat: Infinity, 
          ease: "easeInOut",
          delay: delay * 0.5
        }}
        whileHover={{ scale: 1.2, rotate: 10, transition: { duration: 0.3 } }}
        className={`p-4 rounded-2xl shadow-xl backdrop-blur-md border border-white/20 cursor-pointer ${className}`}
      >
        <Icon size={32} />
      </motion.div>
    </motion.div>
  );
};

