              key={idx} 
              whileHover={{ y: -5 }}
              whileTap={{ scale: 0.98 }}
              className="p-8 rounded-3xl bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-xl transition-all cursor-pointer group focus-visible:ring-4 focus-visible:ring-blue-500"
              tabIndex={0}
              onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') onFeatureClick(feature); }}
            >
              <motion.div 
                className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-6 transition-transform group-hover:scale-110 ${feature.color}`}
                layoutId={`feature-icon-${feature.title}`}
              >
                <feature.icon size={28} />
              </motion.div>
              <h3 className="text-xl font-bold mb-3 text-gray-900 dark:text-white group-hover:text-blue-600 transition-colors">{feature.title}</h3>
              <p className="text-gray-500 leading-relaxed">{feature.desc}</p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

const AIDemoSection = () => {
  const [messages, setMessages] = useState<any[]>([
    { role: 'ai', text: "Hi there! 👋 I'm your AI study buddy. Are you preparing for an upcoming exam or just reviewing? What subject should we tackle first?" }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    // Simulate AI thinking and response
    await new Promise(resolve => setTimeout(resolve, 1200));

    let aiResponseText = "";
    const lowerInput = userMsg.text.toLowerCase();

    if (lowerInput.includes('quantum')) {
      aiResponseText = "Quantum Entanglement is fascinating! 🌌 It describes how particles become linked so that one instantly affects the other, regardless of distance. I can generate a practice quiz on this topic for you.";
    } else if (lowerInput.includes('gatsby')) {
      aiResponseText = "The Great Gatsby is a classic! 🍸 It explores themes of decadence and the American Dream. I can generate an essay outline or character analysis for you in the full app.";
    } else if (lowerInput.includes('calculus') || lowerInput.includes('math')) {
      aiResponseText = "Calculus can be tough, but I can help! ∫ Whether it's derivatives or integrals, I can break it down step-by-step. Download the app for interactive problem solving.";
    } else {
      aiResponseText = `That sounds like a great topic! To generate a full study plan, customized quizzes, and detailed explanations for "${userMsg.text}", check out the full MindCraft app. It's designed to help you ace your exams! 🚀`;
    }

    setMessages(prev => [...prev, { role: 'ai', text: aiResponseText }]);
    setIsTyping(false);
  };

  return (
    <section className="py-24 bg-white dark:bg-gray-950 overflow-hidden">
      <div className="container mx-auto px-6">
        <div className="grid lg:grid-cols-2 gap-16 items-center">
          <div>
             <h2 className="text-3xl lg:text-4xl font-bold mb-6 text-gray-900 dark:text-white">Ask Anything.<br/><span className="text-purple-600">Get Instant Answers.</span></h2>
             <p className="text-lg text-gray-500 mb-8">
               Stuck on a concept? Just ask. Our AI explains complex topics in simple terms, provides examples, and even helps you solve math problems.
             </p>
             <div className="flex flex-wrap gap-3">
               {['Explain Quantum Entanglement', 'Summarize The Great Gatsby', 'Calculus Derivatives'].map(q => (
                 <button key={q} onClick={() => setInput(q)} className="px-4 py-2 rounded-full bg-gray-100 dark:bg-gray-800 text-sm font-medium hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors text-gray-700 dark:text-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-500 hover:scale-105 active:scale-95 transform duration-200">
                   {q}
                 </button>
               ))}
             </div>
          </div>
          <div className="relative">
             <div className="absolute inset-0 bg-gradient-to-r from-blue-500 to-purple-500 rounded-3xl blur-2xl opacity-20 transform rotate-3"></div>
             <div className="relative bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-3xl shadow-2xl overflow-hidden h-[500px] flex flex-col">
                <div className="p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3 bg-gray-50/50 dark:bg-gray-900/50 backdrop-blur">
                  <div className="w-8 h-8 rounded-full bg-purple-600 flex items-center justify-center text-white shadow-lg shadow-purple-500/30"><Sparkles size={16}/></div>
                  <div className="font-bold text-gray-900 dark:text-white">MindCraft AI</div>
                </div>
                <div ref={scrollRef} className="flex-1 p-4 overflow-y-auto space-y-4 scroll-smooth">
                  {messages.map((m, i) => (
                    <motion.div 
                      initial={{ opacity: 0, y: 10, scale: 0.95 }} 
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      transition={{ duration: 0.3 }}
                      key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
                    >
                      <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-200 rounded-tl-none border border-gray-200 dark:border-gray-700'}`}>
                        {m.text}
                      </div>
                    </motion.div>
                  ))}
                  {isTyping && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex justify-start">
                      <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-2xl rounded-tl-none flex gap-1 items-center border border-gray-200 dark:border-gray-700">
                        <motion.span animate={{ y: [0, -5, 0] }} transition={{ duration: 0.6, repeat: Infinity, delay: 0 }} className="w-2 h-2 bg-gray-400 rounded-full"></motion.span>
